pm.test('Código 200', () => pm.response.to.have.status(200));
pm.test('Respuesta JSON', () => pm.response.to.be.json);
const j = pm.response.json();
pm.test('Estructura de éxito: success=true y message', () => { pm.expect(j.success).to.eql(true); pm.expect(j.message).to.be.a('string'); });
pm.test('Rol RESCATISTA', () => pm.expect(j.data.usuario.rol).to.eql('RESCATISTA'));
pm.collectionVariables.set('tokenRescatista', j.data.token);
pm.collectionVariables.set("rescatistaId", j.data.usuario.id);

pm.test("Filtra por especie (200)", () => {
  pm.response.to.have.status(200);
  const animales = pm.response.json().data;
  pm.expect(animales).to.be.an("array");
  animales.forEach(a => pm.expect(a.especie.toLowerCase()).to.eql("perro"));
});

pm.test("Combina filtros (200)", () => {
  pm.response.to.have.status(200);
  const animales = pm.response.json().data;
  pm.expect(animales).to.be.an("array");
  animales.forEach(a => {
    pm.expect(a.especie.toLowerCase()).to.eql("perro");
    pm.expect(a.tamanho).to.eql("GRANDE");
  });
});

pm.test("Tamaño inválido (400)", () => {
  pm.response.to.have.status(400);
  const error = pm.response.json().error;
  pm.expect(error.allowedValues).to.be.an("array");
});

pm.test("Sin coincidencias devuelve lista vacía (200)", () => {
  pm.response.to.have.status(200);
  pm.expect(pm.response.json().data).to.eql([]);
});

pm.test('Código 201', () => pm.response.to.have.status(201));
pm.test('Respuesta JSON', () => pm.response.to.be.json);
const j = pm.response.json();
pm.test('Estructura de éxito: success=true y message', () => { pm.expect(j.success).to.eql(true); pm.expect(j.message).to.be.a('string'); });
pm.test('Queda EN_ADOPCION y con fotos', () => { pm.expect(j.data.estado).to.eql('EN_ADOPCION'); pm.expect(j.data.fotos.length).to.be.above(0); });
pm.collectionVariables.set('animalId', j.data.id);

pm.test("Lista los bloques de contenido (200)", () => {
  pm.response.to.have.status(200);
  const bloques = pm.response.json().data;
  pm.expect(bloques).to.be.an("array").that.is.not.empty;
  bloques.forEach(b => {
    pm.expect(b).to.have.property("seccion");
    pm.expect(b).to.have.property("texto");
  });
});

pm.test("Filtra por sección (200)", () => {
  pm.response.to.have.status(200);
  const bloques = pm.response.json().data;
  pm.expect(bloques).to.have.lengthOf(5);
  bloques.forEach(b => pm.expect(b.seccion).to.eql("CUIDADOS"));
});

